mapper.select:
SELECT a.version AS account_version, m.version AS member_version, m.id AS member_id,
       NULL AS tenant_version
  FROM iam_account a JOIN iam_platform_member m ON m.account_id = a.id
 WHERE a.id = #{accountId} AND a.enabled = TRUE AND a.deleted_at IS NULL AND m.status = #{active}
AND m.id = #{memberId}

SELECT a.version AS account_version, m.version AS member_version, t.version AS tenant_version,
       m.id AS member_id
  FROM iam_account a JOIN iam_tenant_member m ON m.account_id = a.id
  JOIN iam_tenant t ON t.id = m.tenant_id
 WHERE a.id = #{accountId} AND m.tenant_id = #{tenantId}
   AND a.enabled = TRUE AND a.deleted_at IS NULL AND m.status = #{active}
   AND t.enabled = TRUE AND t.deleted_at IS NULL
AND m.id = #{memberId}
